template.script:
/*  */
(function() {
    function initLoginInteractive3D() {
        const canvas = document.getElementById('insilosLoginDigitalTwinCanvas');
        const viewport = document.getElementById('insilosLoginDigitalTwinViewport');
        if (!canvas || !viewport) return;

        // If Three.js and Insilos3D are available, autoInit will mount.
        // Otherwise, provide high-performance 60FPS 3D wireframe gyroscope & particle mesh!
        if (window.THREE && window.Insilos3D) {
            try {
                if (!window.__dtLogin) {
                    window.__dtLogin = window.Insilos3D.initDigitalTwin(viewport, {
                        activeModel: "vlift",
                        renderMode: "pbr",
                        autoRotate: true,
                        autoRotateSpeed: 0.8
                    });
                }
                return;
            } catch(e) {
                console.warn("[Insilos3D Login] Full Three.js init error, falling back to 3D canvas:", e);
            }
        }

        // 60FPS Interactive 3D Wireframe Cybernetic Gyroscope on Canvas
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = canvas.width = viewport.clientWidth || 380;
        let height = canvas.height = viewport.clientHeight || 220;

        let rotX = 0.4, rotY = 0.6, rotZ = 0;
        let targetRotX = 0.4, targetRotY = 0.6;
        let isDragging = false, lastMouseX = 0, lastMouseY = 0;
        let currentModel = 'vlift';

        window.addEventListener('resize', () => {
            if (!viewport || !canvas) return;
            width = canvas.width = viewport.clientWidth || 380;
            height = canvas.height = viewport.clientHeight || 220;
        });

        viewport.addEventListener('mousedown', (e) => {
            isDragging = true;
            lastMouseX = e.clientX;
            lastMouseY = e.clientY;
            viewport.style.cursor = 'grabbing';
        });

        window.addEventListener('mousemove', (e) => {
            if (isDragging) {
                const dx = e.clientX - lastMouseX;
                const dy = e.clientY - lastMouseY;
                targetRotY += dx * 0.01;
                targetRotX += dy * 0.01;
                lastMouseX = e.clientX;
                lastMouseY = e.clientY;
            }
        });

        window.addEventListener('mouseup', () => {
            isDragging = false;
            if (viewport) viewport.style.cursor = 'grab';
        });

        // HUD Toggle Buttons
        const btnVlift = document.getElementById('btnModelVliftLogin');
        const btnCnc = document.getElementById('btnModelCncLogin');
        const btnHud = document.getElementById('btnModeWireLogin');

        if (btnVlift) {
            btnVlift.addEventListener('click', () => {
                currentModel = 'vlift';
                btnVlift.classList.add('active', 'text-cyan');
                if (btnCnc) btnCnc.classList.remove('active', 'text-cyan');
            });
        }
        if (btnCnc) {
            btnCnc.addEventListener('click', () => {
                currentModel = 'cnc';
                btnCnc.classList.add('active', 'text-cyan');
                if (btnVlift) btnVlift.classList.remove('active', 'text-cyan');
            });
        }

        // 3D Nodes Definition
        function getNodes(model) {
            if (model === 'cnc') {
                return [
                    [-70, -35, -45], [70, -35, -45], [70, 35, -45], [-70, 35, -45],
                    [-70, -35, 45], [70, -35, 45], [70, 35, 45], [-70, 35, 45],
                    [0, 45, 0], [0, -45, 0], [-40, 0, 0], [40, 0, 0]
                ];
            }
            // V-LIFT 2500E Industrial Forklift Chassis & Mast geometry
            return [
                [-45, -30, -35], [45, -30, -35], [45, 10, -35], [-45, 10, -35],
                [-45, -30, 35], [45, -30, 35], [45, 10, 35], [-45, 10, 35],
                [35, 60, -20], [35, 60, 20], [35, -30, -20], [35, -30, 20],
                [60, -25, -15], [60, -25, 15]
            ];
        }

        const edges = [
            [0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],
            [0,4],[1,5],[2,6],[3,7],[8,9],[10,11],[8,10],[9,11],[12,13]
        ];

        let animFrame;
        function render() {
            rotX += (targetRotX - rotX) * 0.08;
            rotY += (targetRotY - rotY) * 0.08;
            if (!isDragging) {
                targetRotY += 0.008;
            }

            ctx.clearRect(0, 0, width, height);

            const cx = width / 2;
            const cy = height / 2;
            const fov = 320;

            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);
            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);

            const nodes = getNodes(currentModel);
            const projected = [];

            for (let i = 0; i < nodes.length; i++) {
                const [x, y, z] = nodes[i];
                // Rotate Y
                let x1 = x * cosY - z * sinY;
                let z1 = z * cosY + x * sinY;
                // Rotate X
                let y2 = y * cosX - z1 * sinX;
                let z2 = z1 * cosX + y * sinX + 220;

                const scale = fov / (z2 || 1);
                const px = cx + x1 * scale;
                const py = cy - y2 * scale;
                projected.push({ x: px, y: py, z: z2, scale: scale });
            }

            // Draw Grid Ring on ground
            ctx.beginPath();
            ctx.ellipse(cx, cy + 45, 65, 20, 0, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(0, 240, 255, 0.25)';
            ctx.lineWidth = 1;
            ctx.stroke();

            // Draw Wireframe Edges with Depth Glow
            ctx.strokeStyle = '#00f0ff';
            ctx.lineWidth = 1.6;
            ctx.shadowColor = '#00f0ff';
            ctx.shadowBlur = 8;

            for (let j = 0; j < edges.length; j++) {
                const [i1, i2] = edges[j];
                if (projected[i1] && projected[i2]) {
                    ctx.beginPath();
                    ctx.moveTo(projected[i1].x, projected[i1].y);
                    ctx.lineTo(projected[i2].x, projected[i2].y);
                    ctx.stroke();
                }
            }

            // Draw Vertices / Sensor Hotspots
            for (let k = 0; k < projected.length; k++) {
                const p = projected[k];
                ctx.beginPath();
                ctx.arc(p.x, p.y, Math.max(2, p.scale * 2.2), 0, Math.PI * 2);
                ctx.fillStyle = (k === 8 || k === 9) ? '#10b981' : '#00f0ff';
                ctx.shadowColor = (k === 8 || k === 9) ? '#10b981' : '#00f0ff';
                ctx.shadowBlur = 10;
                ctx.fill();
            }

            ctx.shadowBlur = 0;
            animFrame = requestAnimationFrame(render);
        }

        render();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initLoginInteractive3D);
    } else {
        initLoginInteractive3D();
    }
})();
/*  */
